insert into businesses(name,category,city,address,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Ayres Carpet & Tile Cleaning','Home Services','Ripon',null,'(209) 561-8270','https://www.ayrescarpetandtilecleaning.com/','Ripon-based carpet, tile and upholstery cleaning provider whose official website explicitly lists Manteca, Lathrop and Tracy. Advertises residential and commercial cleaning. Confirm surface type, treatments, drying time, quote and current appointment availability directly. Mountain House coverage and street office address are not established.','approved',true,false,null,0,'editorial_first_party','https://www.ayrescarpetandtilecleaning.com/','first_party_website_desk_check',now()) returning id into bid;
